import { BrowserRouter, Routes, Route } from "react-router-dom";
import Login from "./pages/Login";
import List from "./pages/List";
import Details from "./pages/Details";
import PhotoResult from "./pages/PhotoResult";
import SalaryChart from "./pages/SalaryChart";
import ProtectedRoute from "./components/ProtectedRoute";

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Login />} />
        <Route path="/list" element={<ProtectedRoute><List /></ProtectedRoute>} />
        <Route path="/details/:id" element={<ProtectedRoute><Details /></ProtectedRoute>} />
        <Route path="/photo" element={<ProtectedRoute><PhotoResult /></ProtectedRoute>} />
        <Route path="/chart" element={<ProtectedRoute><SalaryChart /></ProtectedRoute>} />
      </Routes>
    </BrowserRouter>
  );
}
export default App;
